theorem finite_mass_trim {Q : Type*} (S : Finset Q) (w : Q → ℝ) {a : ℝ}
    (ha : 0 < a) (hupper : ∀ q ∈ S, w q ≤ a) (htotal : a ≤ ∑ q ∈ S, w q) :
    ∃ R ⊆ S, a ≤ ∑ q ∈ R, w q ∧ (∑ q ∈ R, w q) ≤ 2*a

theorem carrier_norm_bound {k : ℕ} (T : UnitTube k) {R δ : ℝ}
    (hbase : ‖T.base‖ ≤ R) (hδ1 : δ ≤ 1) {x : Space k} (hx : x ∈ T.carrier δ) :
    ‖x‖ ≤ R+2

theorem discrete_to_measurable_succ {k : ℕ} {m d p : ℝ}
    (hdiscrete : DiscreteEstimate (k+1) m d p) (hd : 1 ≤ d) (hdp : d ≤ p) :
    MeasurableEstimate (k+1) m d p

theorem DiscreteEstimate.to_measurable {k : ℕ} {m d p : ℝ}
    (h : DiscreteEstimate k m d p) (hk : 0 < k) (hd : 1 ≤ d) (hdp : d ≤ p) :
    MeasurableEstimate k m d p

theorem DiscreteEstimate.to_measurable_volume {k : ℕ} {m d p : ℝ}
    (h : DiscreteEstimate k m d p) (hk : 0 < k) (hd : 1 ≤ d) (hdp : d ≤ p) :
    VolumeMeasurableEstimate k m d p

theorem RealCapEstimate.to_measurable {m d p : ℝ}
    (h : RealCapEstimate m d p) (hd : 1 ≤ d) (hdp : d ≤ p) :
    RealCapMeasurableEstimate m d p

theorem bounded_maximal_of_volume {k : ℕ} {d : ℝ}
    (h : VolumeMeasurableEstimate (k+1) (k:ℝ) d d) :
    BoundedEstimate (k+1) d

theorem translated_bounded {n M : ℕ} {F : TubeFamily n M} {Y : Fin M → Set (Space n)}
    (P : Partition F Y) (q : Cell n) :
    (translatedFamily F P.assignment q).Bounded (radius n)

theorem translated_measurable {n M : ℕ} {F : TubeFamily n M} {Y : Fin M → Set (Space n)}
    (P : Partition F Y) (hY : ∀ i, MeasurableSet (Y i)) (q : Cell n)
    (i : Fin (indices P.assignment q).card) : MeasurableSet (translatedShading P q i)

theorem from_diagonal {k : ℕ} {d : ℝ}
    (h : DiagonalDiscreteEstimate (k+1) d) (hd : 1 ≤ d) :
    MaximalShading.Estimate (k+1) d

theorem limiting_density_comparison (j : ℕ) {m lam : ℝ}
    (hm : 3 < m) (hlam : 0 < lam) (hlam1 : lam ≤ 1) :
    lam ^ (max (limitProfile m) 4) ≤ lam ^ (envelope j m)

theorem DiagonalDiscreteEstimate.weaken {n : ℕ} {D d : ℝ}
    (h : DiagonalDiscreteEstimate n D) (hdD : d ≤ D) :
    DiagonalDiscreteEstimate n d

theorem from_restricted_weak {k : ℕ} {a : ℝ}
    (hestimate : OperatorRestrictedWeak.Estimate (k+1) a) (ha : 1 < a) :
    NonnegativeEstimate (k+1) a

theorem DiscreteEstimate.to_cumulative {k : ℕ} {m d p : ℝ}
    (hestimate : DiscreteEstimate k m d p) (hp : 1 ≤ p) :
    CumulativeEstimate k m d p

theorem TwoEnds.to_two_ends {k : ℕ} {m d p : ℝ}
    (h : TwoEnds (k+1) m d p) (hm : 0 ≤ m) :
    TwoEndsDiscreteEstimate (k+1) m d p

theorem TwoEnds.globalize {k : ℕ} {m D C : ℝ}
    (h : TwoEnds (k+1) m D C) (hm : 0 ≤ m) (hD : 1 ≤ D) :
    DiscreteEstimate (k+1) m D (max D C)

theorem TwoEnds.globalize_measurable {k : ℕ} {m D C : ℝ}
    (h : TwoEnds (k+1) m D C) (hm : 0 ≤ m) (hD : 1 ≤ D) :
    VolumeMeasurableEstimate (k+1) m D (max D C)

theorem TwoEndsDiscreteEstimate.remove_two_ends_all_density {k : ℕ} {m D C : ℝ}
    (h : TwoEndsDiscreteEstimate (k+1) m D C) (hm : 0 ≤ m) (hD : 1 ≤ D) :
    DiscreteEstimate (k+1) m D (max D C)

theorem AbsoluteTwoEndsDiscreteEstimate.globalize {k : ℕ} {m D C : ℝ}
    (h : AbsoluteTwoEndsDiscreteEstimate (k+1) m D C) (hm : 0 ≤ m) (hD : 1 ≤ D) :
    DiscreteEstimate (k+1) m D (max D C)

theorem AbsoluteTwoEndsDiscreteEstimate.globalize_measurable {k : ℕ} {m D C : ℝ}
    (h : AbsoluteTwoEndsDiscreteEstimate (k+1) m D C) (hm : 0 ≤ m) (hD : 1 ≤ D) :
    VolumeMeasurableEstimate (k+1) m D (max D C)

theorem to_unit_input {n M : ℕ} {F : TubeFamily n M} {E : Finset (Cell n)}
    {marks : Fin M → Finset (Cell n)} {lengths : Fin M → ℝ}
    {W δ A lam xi B theta width R m alpha a b sep : ℝ}
    (hW : 1 ≤ W) (hL : ∀ i, lengths i ≤ W) (hm : 0 ≤ m)
    (hsep : 0 ≤ sep) (ha : 0 ≤ alpha) (ha1 : alpha ≤ 1)
    (h : Input F E marks lengths δ A lam xi B theta width R m alpha a b sep) :
    MarkedGridNormalization.Input (normalizedFamily F W) E marks
      (δ/W) A (lam/W) xi (B*W) theta width (R/W) m alpha a b sep

theorem bounded_lengths {n M : ℕ} {F : TubeFamily n M} {E : Finset (Cell n)}
    {marks : Fin M → Finset (Cell n)} {lengths : Fin M → ℝ}
    {lengthUpper δ A lam xi B theta width R m alpha a b sep : ℝ}
    (hL : ∀ i, lengths i ≤ lengthUpper) (hm : 0 ≤ m)
    (hsep : 0 ≤ sep) (ha : 0 ≤ alpha) (ha1 : alpha ≤ 1)
    (h : Input F E marks lengths δ A lam xi B theta width R m alpha a b sep) :
    MarkedGridNormalization.Input (normalizedFamily F (dilation lengthUpper)) E marks
      (δ/dilation lengthUpper) A (lam/dilation lengthUpper) xi
      (B*dilation lengthUpper) theta width (R/dilation lengthUpper) m alpha a b sep

theorem prefactor_pos {c B0 alpha theta0 : ℝ}
    (hc : 0 < c) (hB0 : 0 < B0) (ht0 : 0 < theta0) :
    0 < prefactor c B0 alpha theta0

theorem retained_incidence_mass {k M : ℕ} (F : TubeFamily k M) {threshold : ℝ}
    (hthreshold : 0 ≤ threshold) :
    incidenceMass F Finset.univ - threshold*M ≤ incidenceMass F (retainedTubes F threshold)

theorem union_card_ge_one {k M : ℕ} (F : TubeFamily k M) {δ s : ℝ}
    (hδ : 0 < δ) (hs : 0 < s) (hM : 0 < M)
    (hmass : (s/δ)*M ≤ incidenceMass F Finset.univ) : 1 ≤ (F.unionCells.card:ℝ)

theorem weaken_set {n : ℕ} {m D d p : ℝ}
    (h : DiscreteEstimate n m D p) (hd : d ≤ D) :
    DiscreteEstimate n m d p

theorem cap_representative {k : ℕ} (v w : Space k) {r : ℝ}
    (h : projectiveDistance v w ≤ r) :
    ∃ u : Space k, (u = v ∨ u = -v) ∧ dist u w ≤ r

theorem nearRepresentative_in_cap {k : ℕ} (center v : Space k) {r : ℝ}
    (hcap : projectiveDistance v center ≤ r) :
    dist (nearRepresentative center r v) center ≤ r

theorem globalize {k : ℕ} {m D C : ℝ}
    (h : SourceAnalyticInputs.TwoEnds (k+1) m D C) (hm : 0 ≤ m) (hD : 1 ≤ D) :
    VolumeEstimate (k+1) m D (max D C)

def restoreInput {k M : ℕ} {F : TubeFamily (k+1) M}
    {Y Z : Fin M → Set (Space (k+1))} {δ beta : ℝ}
    (P : MeasurableAngularPieces.Pieces F Z δ beta)
    (hsub : ∀ i, Z i ⊆ Y i)
    (hmass : (∑ i,volume.real (Z i)) = ∑ i,volume.real (Y i)) :
    MeasurableAngularPieces.Pieces F Y δ beta

def good (D : LebesgueSampling.Data n M) (F : TubeFamily (n+1) M)
    (δ B alpha theta : ℝ) (J : ℕ) (net : ProjectiveSphereNet.Net n theta) :
    Outcome (Fin M) ↥D.cells → Prop

theorem full_ends_mono {n M : ℕ} (F : TubeFamily n M) {δ B B' alpha : ℝ}
    (hδ : 0 < δ) (hBB : B ≤ B') (h : F.FullTwoEnds δ B alpha) :
    F.FullTwoEnds δ B' alpha

theorem Output.shade_card {k M : ℕ} {F : TubeFamily (k+1) M}
    {δ rho s width B alpha m A : ℝ} {origin : Cell (k+1)}
    (O : Output F δ rho s width B alpha m A origin) (i : Fin O.configuration.M) :
    (O.configuration.family.shade i).card=(F.shade (O.index i)).card

theorem Output.union_card_le {k M : ℕ} {F : TubeFamily (k+1) M}
    {δ rho s width B alpha m A : ℝ} {origin : Cell (k+1)}
    (O : Output F δ rho s width B alpha m A origin) :
    O.configuration.family.unionCells.card ≤ F.unionCells.card

theorem Output.full_two_ends {k M : ℕ} {F : TubeFamily (k+1) M}
    {δ rho s width B alpha m A : ℝ} {origin : Cell (k+1)}
    (O : Output F δ rho s width B alpha m A origin) :
    O.configuration.family.FullTwoEnds O.configuration.δ
      (B*(dilationConstant (k+1) width)^alpha) alpha

def Partition.index {k M : ℕ} {F : TubeFamily k M} {δ rho s : ℝ}
    (P : Partition F δ rho s) (q : Cell k)
    (i : Fin (groupIndices P.assignment q).card) : Fin M

theorem Partition.index_assignment {k M : ℕ} {F : TubeFamily k M} {δ rho s : ℝ}
    (P : Partition F δ rho s) (q : Cell k) (i : Fin (groupIndices P.assignment q).card) :
    P.assignment (P.index q i)=q

theorem Partition.group_union {k M : ℕ} {F : TubeFamily k M} {δ rho s : ℝ}
    (P : Partition F δ rho s) (q : Cell k) :
    (P.groupFamily q).unionCells = groupCells P.shade P.assignment q

theorem Partition.group_comparable {k M : ℕ} {F : TubeFamily k M} {δ rho s : ℝ}
    (P : Partition F δ rho s) (hδ : 0 < δ) (q : Cell k) :
    (P.groupFamily q).Comparable δ P.density

theorem Partition.group_admissible {k M : ℕ} {F : TubeFamily k M} {δ rho s width : ℝ}
    (P : Partition F δ rho s) (h : F.Admissible width δ) (q : Cell k) :
    (P.groupFamily q).Admissible width δ

theorem Partition.group_separated {k M : ℕ} {F : TubeFamily k M} {δ rho s r : ℝ}
    (P : Partition F δ rho s) (h : F.Separated r) (q : Cell k) :
    (P.groupFamily q).Separated r

theorem Partition.group_cap_bound {k M : ℕ} {F : TubeFamily k M} {δ rho s m A : ℝ}
    (P : Partition F δ rho s) (h : F.CapBound δ m A) (q : Cell k) :
    (P.groupFamily q).CapBound δ m A

theorem Partition.population_sum {k M : ℕ} {F : TubeFamily k M} {δ rho s : ℝ}
    (P : Partition F δ rho s) :
    ∑ q ∈ P.bins, (groupIndices P.assignment q).card = M

theorem Partition.union_sum {k M : ℕ} {F : TubeFamily k M} {δ rho s : ℝ}
    (P : Partition F δ rho s) :
    (∑ q ∈ P.bins, (P.groupFamily q).unionCells.card) ≤ F.unionCells.card

theorem unit_ball_cover {n M : ℕ} (F : TubeFamily n M) {width δ : ℝ}
    (hadm : F.Admissible width δ) (hsmall : width*δ ≤ (1:ℝ)/2) :
    ∀ i z, z ∈ F.shade i → dist (cellCenter δ z) ((F.tube i).axisPoint (1/2)) ≤ 1

theorem selected_population {n M : ℕ} {F : TubeFamily n M} {δ alpha lam : ℝ}
    (S : Selection F δ alpha lam) (hδ : 0 < δ) (ha : 0 ≤ alpha) :
    populationCoefficient alpha*(Real.log (2/δ))^(-(2:ℝ))*(M:ℝ) ≤ (S.selected.card:ℝ)

theorem TwoEndsDiscreteEstimate.weaken_density {n : ℕ} {m d p p' : ℝ}
    (h : TwoEndsDiscreteEstimate n m d p) (hpp' : p ≤ p') :
    TwoEndsDiscreteEstimate n m d p'

theorem law_eq_rawLaw {k M : ℕ} {F : TubeFamily (k+1) M} {length : Fin M → ℝ}
    {Full G : Fin M → Set (Space (k+1))} {δ width R L lam c₀ C₀ xi B alpha K beta : ℝ}
    (h : Input F length Full G δ width R L lam c₀ C₀ xi B alpha K beta) :
    SamplingGeometricFailure.law (rawFull Full δ width R L) (rawMarked Full G δ width R L)
      (fun i z => (h.probabilities i z).1) (fun i z => (h.probabilities i z).2.1)
      (fun i z => (h.probabilities i z).2.2) = SphereNetSourceFailure.rawLaw h

theorem optimal_pos {width B alpha theta : ℝ}
    (hw : 0 ≤ width) (hB : 0 < B) (htheta : 0 < theta) :
    0 < optimal width B alpha theta

theorem sourceChoice_pos {width B alpha theta : ℝ}
    (hw : 0 ≤ width) (hB : 0 < B) (htheta : 0 < theta) :
    0 < sourceChoice width B alpha theta

theorem source_legal_two_ends {width B alpha theta : ℝ}
    (hw : 0 ≤ width) (hB : 0 < B) (ha : 0 < alpha) (htheta : 0 < theta) :
    (2*B)*((2*width+1)*sourceChoice width B alpha theta)^alpha ≤ 1/16

theorem source_le_optimal {width B alpha theta : ℝ}
    (hw : 0 ≤ width) (hB : 0 < B) (ha : 0 < alpha) (htheta : 0 < theta) :
    sourceChoice width B alpha theta ≤ optimal width (2*B) alpha theta
